<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { api, type Conversation, type Evidence, type Session, type TurnEvent } from './api'
const session = ref<Session | null>(null), conversations = ref<Conversation[]>([]), activeConversation = ref<Conversation | null>(null)
const evidence = ref<Evidence[]>([]), draft = ref(''), input = ref(''), busy = ref(false), error = ref(''), connected = ref(false), clarification = ref(''), parentTurnId = ref('')
let cancelStream: (() => void) | undefined
let activeTurnId = ''
const canCopy = computed(() => Boolean(activeConversation.value?.lastReply && activeConversation.value?.lastReplyCopyable))
async function newConversation() { try { const item = await api.createConversation(); item.messages ??= []; conversations.value.unshift(item); activeConversation.value = item; evidence.value = []; draft.value = ''; error.value = '' } catch (e) { error.value = e instanceof Error ? e.message : '创建会话失败' } }
async function selectConversation(item: Conversation) { try { const detail = await api.conversation(item.id); detail.messages ??= []; activeConversation.value = detail; evidence.value = detail.last_turn?.evidence ?? detail.evidence ?? []; draft.value = detail.last_turn?.answer ?? detail.lastReply ?? ''; error.value = '' } catch (e) { error.value = e instanceof Error ? e.message : '读取会话失败' } }
async function send() { const text = input.value.trim(); if (!text || busy.value || !activeConversation.value) return; input.value = ''; error.value = ''; const current = activeConversation.value; current.messages.push({ role: 'user', content: text }); busy.value = true; connected.value = false; draft.value = ''; clarification.value = ''; evidence.value = []; try { const turn = await api.createTurn(current.id, text, parentTurnId.value || undefined); parentTurnId.value = ''; activeTurnId = turn.id; cancelStream?.(); cancelStream = api.streamEvents(turn.id, (event) => handleEvent(current, event), () => { busy.value = false; connected.value = true; activeTurnId = '' }, (reason) => { error.value = reason; busy.value = false; connected.value = false; activeTurnId = '' }) } catch (e) { error.value = e instanceof Error ? e.message : '提交失败'; busy.value = false } }
function handleEvent(current: Conversation, event: TurnEvent) { connected.value = true; if (event.type === 'status' && event.status === 'ASKING') { clarification.value = event.clarification ?? '请补充更多问题细节。'; parentTurnId.value = activeTurnId } if (event.type === 'evidence') evidence.value = event.evidence ?? []; if (event.type === 'delta') draft.value += event.text ?? ''; if (event.type === 'completed') { if (event.status === 'ASKING') { clarification.value = event.clarification ?? clarification.value; error.value = '需要补充信息后才能继续'; } else if (event.status === 'DONE') { current.lastReply = draft.value; current.lastReplyCopyable = false; current.evidence = evidence.value; current.messages.push({ role: 'assistant', content: draft.value, mock: true }) } else if (event.status === 'CANCELLED') { error.value = '生成已停止' } else if (event.status === 'FAILED') { error.value ||= '生成失败，请重试' } busy.value = false } if (event.type === 'error') error.value = event.message ?? '生成失败' }
async function stop() { if (activeTurnId) { try { await api.cancelTurn(activeTurnId) } catch (e) { error.value = e instanceof Error ? e.message : '取消失败' } } cancelStream?.(); cancelStream = undefined; activeTurnId = ''; busy.value = false }
async function copyDraft() { if (canCopy.value && draft.value) await navigator.clipboard.writeText(draft.value) }
onMounted(async () => { try { session.value = await api.session(); conversations.value = await api.conversations(); if (conversations.value.length) await selectConversation(conversations.value[0]); else await newConversation() } catch (e) { error.value = e instanceof Error ? e.message : '工作区加载失败' } })
onUnmounted(() => cancelStream?.())
</script>
<template>
<div v-if="clarification" style="position:fixed;top:78px;left:50%;transform:translateX(-50%);z-index:5;max-width:min(520px,calc(100vw - 24px));padding:10px 14px;border:1px solid #e6d39a;border-radius:6px;background:#fff8e3;color:#795b19;font-size:12px"><strong style="display:block;margin-bottom:3px">需要补充信息</strong><span>{{ clarification }}</span></div>
<div class="shell"><header class="topbar"><div class="brand"><span class="brand-mark">ER</span><div><strong>客服工作台</strong><small>Evidence-backed support</small></div></div><div class="top-meta"><span class="status-dot" :class="{ live: connected }"></span>{{ session?.shopName ?? '演示店铺' }}<span class="user">{{ session?.displayName ?? 'Demo operator' }}</span></div></header>
<div class="workspace"><aside class="sidebar panel"><div class="side-heading"><div><p class="kicker">CONVERSATIONS</p><h2>近期会话</h2></div><button class="icon-btn" title="新建会话" @click="newConversation">+</button></div><button class="new-chat" @click="newConversation">＋ 新建会话</button><div class="conversation-list"><button v-for="item in conversations" :key="item.id" class="conversation" :class="{ selected: item.id === activeConversation?.id }" @click="selectConversation(item)"><span class="conversation-title">{{ item.title }}</span><span class="conversation-time">{{ item.messages.length ? `${item.messages.length} 条消息` : '空会话' }}</span></button></div><div class="scope"><p class="kicker">ACCESS SCOPE</p><strong>{{ session?.shopName ?? '演示店铺' }}</strong><span>{{ session?.role ?? '客服运营' }} · 只读知识</span></div></aside>
<main class="chat panel"><div class="chat-heading"><div><p class="kicker">ASSISTED REPLY</p><h1>{{ activeConversation?.title ?? '新会话' }}</h1></div><span class="env-badge">M1 MOCK</span></div><div class="messages"><div v-if="!activeConversation?.messages.length && !busy" class="welcome"><div class="welcome-icon">✦</div><h2>从一个客户问题开始</h2><p>答案会附带可追溯的知识证据。当前为隔离环境，生成内容仅供预览。</p></div><div v-for="(message, index) in activeConversation?.messages" :key="index" class="message" :class="message.role"><div class="avatar">{{ message.role === 'user' ? '你' : 'AI' }}</div><div><div class="message-meta">{{ message.role === 'user' ? '客服' : '助手' }}<span v-if="message.mock" class="mock-tag">模拟数据</span></div><div class="bubble">{{ message.content }}</div></div></div><div v-if="busy" class="message assistant"><div class="avatar">AI</div><div><div class="message-meta">助手<span class="typing">正在检索证据…</span></div><div class="bubble loading"><i></i><i></i><i></i></div></div></div></div><div v-if="error" class="error-banner">{{ error }}</div><form class="composer" @submit.prevent="send"><textarea v-model="input" :disabled="busy" placeholder="输入客户问题…" rows="3" @keydown.enter.exact.prevent="send"></textarea><div class="composer-actions"><span>Enter 发送 · Shift + Enter 换行</span><div><button v-if="busy" type="button" class="stop-btn" @click="stop">停止</button><button v-else type="submit" class="send-btn" :disabled="!input.trim()">发送 <span>↗</span></button></div></div></form></main>
<aside class="evidence panel"><div class="evidence-heading"><div><p class="kicker">TRACEABILITY</p><h2>证据与引用</h2></div><span class="count">{{ evidence.length }}</span></div><div v-if="!evidence.length" class="evidence-empty"><div class="doc-icon">▤</div><p>发送问题后，这里会显示经过权限过滤的来源。</p></div><article v-for="item in evidence" :key="item.id" class="evidence-card"><div class="evidence-card-top"><span>{{ item.sourceType }}</span><span class="score">{{ Math.round(item.score * 100) }}%</span></div><h3>{{ item.title }}</h3><p>{{ item.snippet }}</p><footer>{{ item.documentId }} · {{ item.versionId }}</footer></article><div v-if="draft" class="draft-panel"><div class="draft-head"><h3>回复草稿</h3><span class="mock-tag">模拟数据</span></div><p>{{ draft }}</p><button class="copy-btn" disabled title="模拟结果不可复制" @click="copyDraft">复制草稿 <span>仅真实生成可用</span></button></div></aside></div></div>
</template>
<style>
:root{color:#17231f;background:#f6f8f6;font-family:Inter,ui-sans-serif,system-ui,sans-serif;font-synthesis:none}*{box-sizing:border-box}body{margin:0;min-width:320px}button,textarea{font:inherit}button{cursor:pointer}.shell{min-height:100vh;background:#f6f8f6}.topbar{height:70px;display:flex;align-items:center;justify-content:space-between;padding:0 28px;border-bottom:1px solid #e1e8e3;background:#fff}.brand{display:flex;align-items:center;gap:11px}.brand-mark{width:32px;height:32px;display:grid;place-items:center;border-radius:8px;background:#143f35;color:#e9f4ed;font-size:11px;font-weight:800}.brand strong{display:block;font-size:14px}.brand small{color:#85958d;font-size:10px}.top-meta{display:flex;align-items:center;gap:9px;color:#52635b;font-size:12px}.user{padding-left:14px;margin-left:4px;border-left:1px solid #dfe7e2;color:#223b32;font-weight:600}.status-dot{width:7px;height:7px;border-radius:50%;background:#d7a752}.status-dot.live{background:#36a576}.workspace{display:grid;grid-template-columns:235px minmax(440px,1fr) 310px;gap:14px;max-width:1500px;margin:0 auto;padding:18px;min-height:calc(100vh - 70px)}.panel{background:#fff;border:1px solid #e2e9e4;border-radius:9px;min-height:0}.sidebar,.evidence{display:flex;flex-direction:column;padding:20px 16px}.chat{display:flex;flex-direction:column;padding:25px 28px 20px}.kicker{margin:0 0 6px;color:#8a9a92;font-size:10px;letter-spacing:.13em;font-weight:700}h1,h2,h3,p{margin-top:0}h1{font-size:19px;margin-bottom:0}h2{font-size:16px;margin:0}.side-heading,.chat-heading,.evidence-heading{display:flex;align-items:flex-start;justify-content:space-between}.icon-btn{width:28px;height:28px;border:1px solid #dce6df;border-radius:6px;color:#174f40;background:#fff;font-size:21px}.new-chat{width:100%;margin:22px 0 14px;border:0;border-radius:6px;padding:10px;background:#e8f2ec;color:#1c5a45;text-align:left;font-size:12px;font-weight:700}.conversation-list{overflow:auto}.conversation{display:block;width:100%;border:0;border-left:2px solid transparent;padding:11px 10px;background:transparent;text-align:left;color:#44554d}.conversation.selected{border-left-color:#267e5d;background:#f0f6f1;color:#163f32}.conversation-title,.conversation-time{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.conversation-title{font-size:12px;font-weight:600}.conversation-time{margin-top:4px;color:#9aa8a1;font-size:10px}.scope{margin-top:auto;border-top:1px solid #edf1ee;padding-top:16px;display:flex;flex-direction:column;gap:4px;font-size:11px;color:#77877f}.scope strong{color:#27473a;font-size:12px}.env-badge,.mock-tag{display:inline-flex;align-items:center;border-radius:4px;background:#fff4d8;color:#9b6b16;font-size:10px;font-weight:700;padding:4px 7px}.messages{flex:1;overflow:auto;padding:32px 3px 22px}.welcome{max-width:340px;margin:16vh auto 0;text-align:center;color:#708077}.welcome-icon{width:42px;height:42px;display:grid;place-items:center;margin:0 auto 17px;border-radius:50%;background:#e8f2ec;color:#2f8865;font-size:23px}.welcome h2{color:#29473a;font-size:17px}.welcome p{line-height:1.65;font-size:12px}.message{display:flex;gap:10px;max-width:790px;margin:0 auto 22px}.message.user{flex-direction:row-reverse}.message.user>div:last-child{text-align:right}.avatar{width:28px;height:28px;flex:0 0 28px;display:grid;place-items:center;border-radius:7px;background:#e7f0eb;color:#26634c;font-size:10px;font-weight:700}.user .avatar{background:#dce8f5;color:#3c6591}.message-meta{margin:2px 0 6px;color:#85938c;font-size:10px}.message-meta .mock-tag{margin-left:8px;padding:2px 5px;font-size:9px}.bubble{display:inline-block;max-width:min(650px,100%);border:1px solid #e3ebe5;border-radius:3px 10px 10px 10px;padding:12px 14px;color:#31473d;font-size:13px;line-height:1.65;text-align:left;white-space:pre-wrap}.user .bubble{border:0;border-radius:10px 3px 10px 10px;background:#eaf1f8;color:#335572}.loading{min-width:68px}.loading i{display:inline-block;width:5px;height:5px;margin:0 2px;border-radius:50%;background:#7aa68f;animation:pulse 1.1s infinite}@keyframes pulse{0%,80%,100%{opacity:.3}40%{opacity:1}}.typing{margin-left:9px;color:#43856a}.composer{border:1px solid #dfe8e1;border-radius:8px;overflow:hidden;background:#fbfcfb}.composer textarea{width:100%;resize:none;border:0;outline:0;padding:13px 14px 4px;background:transparent;color:#263f34;font-size:13px;line-height:1.5}.composer textarea::placeholder{color:#a1aea7}.composer-actions{display:flex;align-items:center;justify-content:space-between;padding:7px 10px 9px 14px;color:#9aa8a1;font-size:10px}.send-btn,.stop-btn{border:0;border-radius:5px;padding:8px 13px;color:#fff;background:#1b654d;font-size:11px;font-weight:700}.send-btn:disabled{opacity:.45;cursor:not-allowed}.stop-btn{background:#a3453e}.error-banner{margin:0 0 9px;padding:9px 11px;border:1px solid #f0d3d0;background:#fff5f4;color:#a3453e;border-radius:5px;font-size:11px}.count{min-width:23px;height:23px;display:grid;place-items:center;border-radius:50%;background:#edf4ef;color:#35745a;font-size:10px;font-weight:700}.evidence-empty{margin:auto 14px;text-align:center;color:#95a29b;font-size:11px;line-height:1.6}.doc-icon{margin:0 auto 12px;color:#96b5a1;font-size:28px}.evidence-card{margin-top:18px;border:1px solid #e3ebe5;border-radius:6px;padding:11px}.evidence-card-top{display:flex;justify-content:space-between;color:#799087;font-size:9px;text-transform:uppercase}.score{color:#408362;font-weight:700}.evidence-card h3{margin:8px 0 5px;color:#315141;font-size:12px}.evidence-card p{margin:0 0 9px;color:#6e7f76;font-size:11px;line-height:1.5}.evidence-card footer{border-top:1px solid #edf1ee;padding-top:7px;color:#9aa8a1;font-size:9px}.draft-panel{margin-top:auto;border-top:1px solid #e7eee9;padding-top:16px}.draft-head{display:flex;align-items:center;justify-content:space-between}.draft-head h3{margin:0;color:#315141;font-size:12px}.draft-panel p{margin:9px 0;color:#52645a;font-size:11px;line-height:1.6}.copy-btn{width:100%;border:1px solid #dfe7e1;border-radius:5px;padding:8px;background:#f5f7f5;color:#89968f;font-size:10px;cursor:not-allowed}.copy-btn span{display:block;margin-top:2px;font-size:9px}@media(max-width:1060px){.workspace{grid-template-columns:200px minmax(380px,1fr)}.evidence{grid-column:1/-1;min-height:190px}}@media(max-width:720px){.topbar{height:60px;padding:0 14px}.top-meta{font-size:0}.user{display:none}.workspace{display:flex;flex-direction:column;gap:8px;padding:8px;min-height:calc(100vh - 60px)}.sidebar{order:1;flex:0 0 auto;max-height:154px;overflow:hidden;margin:0;min-height:0}.new-chat{margin:12px 0 8px}.conversation-list{display:flex;gap:4px;overflow:auto;min-height:48px}.conversation{min-width:135px;padding:9px 10px}.scope{display:none}.chat{order:2;flex:1 1 auto;min-height:calc(100vh - 250px);padding:18px 14px 14px}.messages{min-height:180px;padding-top:22px}.welcome{margin:8vh auto 0}.evidence{order:3;flex:0 0 auto;min-height:160px;max-height:300px;overflow:auto;margin:0}.evidence-empty{margin:24px 14px}.composer-actions>span{display:none}}
</style>
